// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata addrs) public {
        // Ensure all addresses are non-zero
        vm.assume(addrs.length <= 10); // maxNodeDelegatorCount = 10
        for (uint256 i = 0; i < addrs.length; i++) {
            vm.assume(addrs[i] != address(0));
        }

        // Record paused state before the call
        bool pausedBefore = c.paused();

        // Call addNodeDelegatorContractToQueue; it should not revert
        c.addNodeDelegatorContractToQueue(addrs);

        // Assert that paused state is unchanged
        bool pausedAfter = c.paused();
        assertTrue(pausedBefore == pausedAfter, "paused state changed");
    }
}

