pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[10] memory fuzzDelegators) public {
        // Initialize contract
        // Use a fresh deployment per fuzz run, already done in setUp
        // The fuzz parameter provides potential node delegator addresses
        // We'll call addNodeDelegatorContractToQueue with some subset
        // First, ensure at least one non-zero address
        vm.assume(fuzzDelegators[0] != address(0));
        // We'll call addNodeDelegatorContractToQueue with the first few non-zero addresses
        // Build the array of valid addresses
        address[] memory validDelegators = new address[](fuzzDelegators.length);
        uint256 count = 0;
        for (uint256 i = 0; i < fuzzDelegators.length; i++) {
            if (fuzzDelegators[i] != address(0)) {
                validDelegators[count] = fuzzDelegators[i];
                count++;
            }
        }
        // If no valid addresses, skip
        vm.assume(count > 0);
        // Trim the array
        assembly {
            mstore(validDelegators, count)
        }
        // Call addNodeDelegatorContractToQueue; it may revert due to max count
        // Get the current maxNodeDelegatorCount
        uint256 maxCount = c.maxNodeDelegatorCount();
        // If we try to add more than maxCount, expect revert; otherwise no revert
        bool reverted = false;
        try c.addNodeDelegatorContractToQueue(validDelegators) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // After the call, check that if it succeeded, the queue length <= maxNodeDelegatorCount
        uint256 queueLength = c.getNodeDelegatorQueue().length;
        uint256 newMaxCount = c.maxNodeDelegatorCount();
        // The invariant: If the call did not revert, the queue length must be <= newMaxCount
        assertTrue(reverted || (queueLength <= newMaxCount));
    }
}

