pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata addrs) public {
        // The rule: when addrs is empty, addNodeDelegatorContractToQueue should not revert
        // when maxNodeDelegatorCount is 10 (reference), but it should revert when maxNodeDelegatorCount is 0 (mutant).
        // We cannot read maxNodeDelegatorCount directly, so we test the behavior.
        // After initialization, the reference allows at most 10 node delegators, so empty array always works.
        // The mutant sets maxNodeDelegatorCount=0, so any non-zero length would revert, but empty array should also revert
        // because the check `nodeDelegatorQueue.length + length > maxNodeDelegatorCount` becomes 0 + 0 > 0 = false (no revert).
        // Actually both versions pass with empty array. We need a different rule.
        // Instead, use a non-empty array and check that if it's too large it reverts for both, but the boundary differs.
        // The invariant: after initialization, the maximum number of node delegators that can be added in one call is maxNodeDelegatorCount.
        // For reference: maxNodeDelegatorCount=10, so adding 11 should revert.
        // For mutant: maxNodeDelegatorCount=0, so adding 1 should revert.
        uint256 length = addrs.length;
        // Bound length to test both cases: reference allows up to 10, mutant allows 0.
        length = bound(length, 0, 20);
        // Create dummy addresses for simplicity (no need for real contracts)
        address[] memory input = new address[](length);
        for (uint256 i; i < length; i++) {
            input[i] = address(uint160(i + 1));
        }
        // Try to add them
        (bool ok, ) = address(c).call(abi.encodeWithSignature("addNodeDelegatorContractToQueue(address[])", input));
        // The rule: if length > 10, revert; else succeed. For mutant: if length > 0, revert; else succeed.
        // But we don't know which version we have. However, the reference always allows length <= 10.
        // So the property: after any number of calls, we can always add at most 10 node delegators.
        // Actually, we need a property that the reference satisfies and mutant breaks.
        // The mutant breaks because it rejects all non-empty arrays immediately.
        // Therefore, the property: for any length from 0 to 10, the call succeeds (reference).
        // But that's not true for mutant because mutant rejects length 1.
        // So we can test: if length == 1, the reference succeeds and mutant fails.
        // But we need a general rule over fuzz params.
        // A better rule: for any non-empty array, the call reverts if and only if length > 10 (reference) OR it always reverts (mutant).
        // Actually, mutant always reverts for length > 0.
        // So the rule: if length == 0, ok; if length > 0 and length <= 10, reference succeeds, mutant reverts.
        // So we can check: when length == 1, ok should be true for reference and false for mutant.
        // But we can't distinguish which version we are testing.
        // The only way is to test a property that is monotonic: the number of successful calls is limited.
        // But with one call, we can only observe success or revert.
        // The mutant always reverts for length > 0, so if we see a revert for length = 1, we know it's mutant.
        // But we need a general rule that holds for reference for all inputs.
        // The reference only reverts if length > 10 or if the total added exceeds maxNodeDelegatorCount (which starts at 10).
        // Since we only make one call, the reference succeeds for length <= 10.
        // So the property: for length values 0 to 10, the call should succeed (reference).
        // Mutant fails for length >= 1.
        // However, we cannot write "assertTrue(ok)" for all lengths because the test would fail on reference for length 11.
        // We need to restrict the input: only test lengths where reference succeeds.
        vm.assume(length <= 10);
        assertTrue(ok, "Call should succeed for length <= 10");
    }
}

